  $("hStart").style.left = (trackLeft + x0) + "px";
  $("hEnd").style.left = (trackLeft + x1) + "px";
  $("railBand").style.left = (trackLeft + x0) + "px";
  $("railBand").style.width = (x1 - x0) + "px";
  $("flagStart").textContent = `${state.d0} Aug`;
