}

input.new_string:
  block.style.top = `${top}px`;
  block.style.height = `${height}px`;
  block.dataset.slug = slot.slug;
  // What actually fits, measured off the block's own height rather than the
  // column width — a 20-minute slot is cramped on any screen. The title is the
  // one thing that never goes: the clock is readable off the axis beside it,
  // and the hover card carries the rest.
